class _JsonDuplicateMember(ValueError):
    """Internal: a JSON object repeated a member name."""


def _decode_json_index_numeric(kind: int, key: bytes) -> Any:
    """Decode a canonical integer/float bucket key back to its number.

    Structural validity (ASCII, finite) is enforced by
    :func:`_check_json_index_bucket_key`; this only re-parses.
    """
    if kind == _JSON_TAG_INTEGER:
        return int(key.decode("ascii"))
    return float(key.decode("ascii"))


def _check_json_index_bucket_key(kind: int, key: Any) -> None:
    """Validate one bucket key blob for its group's kind."""
    if not isinstance(key, bytes):
        raise TypeError("bucket key must be bytes")
    if kind in _JSON_INDEX_EMPTY_KINDS:
        if key:
            raise ValueError(
                "a boolean or null bucket key must be the empty blob"
            )
        return
    if kind == _JSON_TAG_STRING:
        # Strings carry arbitrary text; the key must be valid UTF-8.
        try:
            key.decode("utf-8")
        except UnicodeDecodeError as error:
            raise ValueError("string bucket key must be valid UTF-8") from error
        return
    try:
        text = key.decode("ascii")
    except UnicodeDecodeError as error:
        raise ValueError("numeric bucket key must be ASCII") from error
    if kind == _JSON_TAG_INTEGER:
        digits = text[1:] if text[:1] == "-" else text
        if not digits or any(ch not in "0123456789" for ch in digits):
            raise ValueError("integer bucket key must be canonical ASCII decimal")
    elif kind == _JSON_TAG_FLOAT:
        try:
            value = float(text)
        except ValueError as error:
            raise ValueError("float bucket key must be an ASCII number") from error
        if not math.isfinite(value):
            raise ValueError("float bucket key must be finite")
        if repr(value).encode("ascii") != key:
            raise ValueError("float bucket key must be the canonical repr spelling")


def _check_json_value(value: Any) -> None:
    """Validate a find_json / json_search_receipt scalar query value."""
    if isinstance(value, bool) or isinstance(value, str) or value is None:
        return
    if isinstance(value, int):
        return
    if isinstance(value, float):
        if not math.isfinite(value):
            raise ValueError("value must be a finite number")
        return
    raise TypeError("value must be str, int, float, bool or None")


def _parse_json_pointer(pointer: Any) -> tuple[str, ...]:
    """Parse an RFC 6901 JSON Pointer into its tuple of unescaped tokens.

    The empty string is the root pointer and yields ``()``. A non-``str``
    pointer raises TypeError; a non-empty pointer that does not start with
    ``/`` or a reference token carrying an escape other than ``~0`` /
    ``~1`` raises ValueError.
    """
    if not isinstance(pointer, str):
        raise TypeError("pointer must be a string")
    if pointer == "":
        return ()
    if not pointer.startswith("/"):
        raise ValueError("a non-empty JSON Pointer must start with '/'")
    tokens: list[str] = []
    for raw in pointer.split("/")[1:]:
        if "~" not in raw:
            tokens.append(raw)
            continue
        decoded: list[str] = []
        index = 0
        while index < len(raw):
            char = raw[index]
            if char == "~":
                if index + 1 >= len(raw) or raw[index + 1] not in "01":
                    raise ValueError("JSON Pointer escape must be '~0' or '~1'")
                decoded.append("~" if raw[index + 1] == "0" else "/")
                index += 2
            else:
                decoded.append(char)
                index += 1
        tokens.append("".join(decoded))
    return tuple(tokens)


def _json_pointer_canonical(tokens: tuple[str, ...]) -> str:
    """Canonical RFC 6901 spelling of parsed pointer tokens."""
    if not tokens:
        return ""
    return "".join(
        "/" + token.replace("~", "~0").replace("/", "~1") for token in tokens
    )


def _json_reject_duplicates(pairs: Any) -> dict:
    document: dict = {}
    for key, value in pairs:
        if key in document:
            raise _JsonDuplicateMember(f"duplicate JSON object member {key!r}")
        document[key] = value
    return document


def _json_reject_constant(value: str) -> Any:
    # RFC 8259 has no NaN/Infinity; Python's json accepts them by default.
    raise ValueError(f"{value} is not valid JSON")


def _json_scalar_at(payload: bytes, tokens: tuple[str, ...]) -> Any:
    """Resolve parsed pointer tokens against strict UTF-8 JSON bytes.

    Returns the addressed scalar, or the ``_JSON_MISSING`` sentinel when
    the payload is not strict UTF-8 JSON, repeats an object member name at
    any depth, carries a non-finite number, the pointer traverses a missing
    member/element or a non-container, indexes an array with a non-numeric
    (``-`` included), leading-zero or out-of-range token, or the addressed
    value is an object or array rather than a scalar.
    """
    try:
        text = payload.decode("utf-8")
        document = json.loads(
            text,
            object_pairs_hook=_json_reject_duplicates,
            parse_constant=_json_reject_constant,
        )
    except (UnicodeDecodeError, ValueError):
        return _JSON_MISSING
    current = document
    for token in tokens:
        if isinstance(current, dict):
            if token not in current:
                return _JSON_MISSING
            current = current[token]
        elif isinstance(current, list):
            # "-" addresses the nonexistent append position; array tokens
            # are plain decimal indices with no leading zeroes (RFC 6901).
            if (
                not token
                or token == "-"
                or any(char not in "0123456789" for char in token)
                or (len(token) > 1 and token[0] == "0")
            ):
                return _JSON_MISSING
            index = int(token)
            if index >= len(current):
                return _JSON_MISSING
            current = current[index]
        else:
            return _JSON_MISSING
    if current is None or isinstance(current, (str, bool, int, float)):
        return current
    return _JSON_MISSING


def _json_scalar_matches(found: Any, value: Any) -> bool:
    """Whether an addressed JSON scalar equals a query, per JSON kind.

    Strings, booleans and null only match their own kind; ints and floats
    are both JSON numbers and compare by numeric value (a JSON ``true`` is
    never the number 1).
    """
    if value is None:
        return found is None
    if isinstance(value, bool):
        return isinstance(found, bool) and found == value
    if isinstance(value, str):
        return isinstance(found, str) and found == value
    # int and float are both JSON numbers: numeric equality across the two.
    return (
        isinstance(found, (int, float))
        and not isinstance(found, bool)
        and found == value
    )


def _json_entry_matches(
    payload: bytes, tokens: tuple[str, ...], value: Any
) -> bool:
    """Whether one stored payload is a find_json hit."""
    if payload.startswith(_ENC_MAGIC):
        # An AES-256-GCM envelope is never plain JSON; it takes no part.
        return False
    found = _json_scalar_at(payload, tokens)
    return found is not _JSON_MISSING and _json_scalar_matches(found, value)


def _json_entry_scalar(payload: bytes, tokens: tuple[str, ...]) -> Any:
    """The addressed scalar of one stored payload, or ``_JSON_MISSING``.

    Same resolution rules as :func:`_json_entry_matches` — an AES-256-GCM
    envelope is never parsed — but returns the resolved scalar itself so the
    JSON field retrieval index can group entries by their addressed value.
    """
    if payload.startswith(_ENC_MAGIC):
        return _JSON_MISSING
    return _json_scalar_at(payload, tokens)


def _json_index_tag_of_scalar(value: Any) -> int:
    """Value-type tag of a resolved JSON scalar (mirrors _encode_json_value)."""
    if isinstance(value, bool):
        return _JSON_TAG_TRUE if value else _JSON_TAG_FALSE
    if value is None:
        return _JSON_TAG_NULL
    if isinstance(value, str):
        return _JSON_TAG_STRING
    if isinstance(value, int):
        return _JSON_TAG_INTEGER
    return _JSON_TAG_FLOAT


def _json_index_key_of_scalar(kind: int, value: Any) -> bytes:
    """Canonical encoded bucket key of a resolved scalar of ``kind``."""
    if kind == _JSON_TAG_STRING:
        return value.encode("utf-8")
    if kind == _JSON_TAG_INTEGER:
        return str(value).encode("ascii")
    if kind == _JSON_TAG_FLOAT:
        # -0.0 and 0.0 are equal JSON numbers (find_json compares them by
        # value), so normalize a negative zero before spelling the key.
        return repr(value + 0.0).encode("ascii")
    return b""


def _build_json_search_index(
    log: "AuditLog", tokens: tuple[str, ...], size: int
) -> "JsonSearchIndex":
    """Construct the unsigned :class:`JsonSearchIndex` snapshot artifact.

    Assumes the pointer is already parsed and ``size`` resolved and
    rebuildable by the caller; all state is read from the log without
    mutating it.
    """
    first = log._retain_from
    if size == 0:
        root = _hash_parts(log._hash_name, _EMPTY_DOMAIN)
    else:
        # Mirror merkle_root: a non-empty prefix released by prune cannot
        # be rebuilt. (The empty root is universal and needs no data.)
        log._require_retained_snapshot(size)
        root = log._fold_occupied(log._occupied_at(size))
    head = log._chain_head_at(size)
    items = tuple(log.entry(index) for index in range(first, size))
    if items:
        _, proof = log.batch_inclusion_proof(tuple(range(first, size)), size)
    else:
        proof = ()
    # tag -> canonical key -> ascending absolute indices
    collected: dict[int, dict[bytes, list[int]]] = {}
    for entry in items:
        scalar = _json_entry_scalar(entry.payload, tokens)
        if scalar is _JSON_MISSING:
            continue
        if isinstance(scalar, float) and not math.isfinite(scalar):
            # Strict JSON payloads can never reach here; stay defensive.
            continue
        kind = _json_index_tag_of_scalar(scalar)
        key = _json_index_key_of_scalar(kind, scalar)
        collected.setdefault(kind, {}).setdefault(key, []).append(entry.index)
    groups: list[JsonSearchIndexGroup] = []
    for kind in sorted(collected):
        keyed = collected[kind]
        if kind == _JSON_TAG_STRING:
            ordered_keys = sorted(keyed)
        elif kind in _JSON_INDEX_EMPTY_KINDS:
            ordered_keys = (b"",)
        else:
            ordered_keys = sorted(
                keyed, key=lambda blob: _decode_json_index_numeric(kind, blob)
            )
        buckets = tuple(
            JsonSearchIndexBucket(key=key, hits=tuple(keyed[key]))
            for key in ordered_keys
        )
        groups.append(JsonSearchIndexGroup(kind=kind, buckets=buckets))
    return JsonSearchIndex(
        version=_JSON_SEARCH_INDEX_VERSION,
        hash_name=log._hash_name,
        size=size,
        root=root,
        head=head,
        retain_from=first,
        pointer=_json_pointer_canonical(tokens),
        items=items,
        proof=proof,
        groups=tuple(groups),
    )


def _parse_json_pointer_tuple(pointers: Any) -> tuple[tuple[str, ...], ...]:
    """Validate the non-empty ordered tuple of RFC 6901 pointers.

    Each element must be a ``str`` (TypeError otherwise), parse as an RFC
    6901 JSON Pointer (ValueError on malformed syntax), and the canonical
    spellings must be pairwise distinct and in strictly ascending order
    (ValueError for an empty tuple, a duplicate or a misordered pair).
    Returns the parsed token tuples in the given order.
    """
    if not isinstance(pointers, tuple):
        raise TypeError("pointers must be a tuple of strings")
    if not pointers:
        raise ValueError("pointers must be a non-empty tuple")
    parsed: list[tuple[str, ...]] = []
    previous: str | None = None
    for pointer in pointers:
        tokens = _parse_json_pointer(pointer)
        canonical = _json_pointer_canonical(tokens)
        if previous is not None and not canonical > previous:
            raise ValueError(
                "pointers must be unique and in strictly ascending order"
            )
        previous = canonical
        parsed.append(tokens)
    return tuple(parsed)


def _json_multi_groups_for_tokens(
    items: tuple["Entry", ...], token_sets: tuple[tuple[str, ...], ...]
) -> tuple[JsonSearchIndexGroup, ...]:
    """Reproduce one pointer's ordered hit groups from covered entries.

    Mirrors :func:`_build_json_search_index`'s grouping exactly; each group
    is empty (``groups == ()``) when no covered entry resolves to a
    queryable scalar for that pointer.
    """
    collected: dict[int, dict[bytes, list[int]]] = {}
    for entry in items:
        scalar = _json_entry_scalar(entry.payload, token_sets)
        if scalar is _JSON_MISSING:
            continue
        if isinstance(scalar, float) and not math.isfinite(scalar):
            # Strict JSON payloads can never reach here; stay defensive.
            continue
        kind = _json_index_tag_of_scalar(scalar)
        key = _json_index_key_of_scalar(kind, scalar)
        collected.setdefault(kind, {}).setdefault(key, []).append(entry.index)
    groups: list[JsonSearchIndexGroup] = []
    for kind in sorted(collected):
        keyed = collected[kind]
        if kind == _JSON_TAG_STRING:
            ordered_keys = sorted(keyed)
        elif kind in _JSON_INDEX_EMPTY_KINDS:
            ordered_keys = (b"",)
        else:
            ordered_keys = sorted(
                keyed, key=lambda blob: _decode_json_index_numeric(kind, blob)
            )
        buckets = tuple(
            JsonSearchIndexBucket(key=key, hits=tuple(keyed[key]))
            for key in ordered_keys
        )
        groups.append(JsonSearchIndexGroup(kind=kind, buckets=buckets))
    return tuple(groups)


def _build_json_multi_index(
    log: "AuditLog",
    token_sets: tuple[tuple[str, ...], ...],
    size: int,
) -> "JsonMultiIndex":
    """Construct the unsigned :class:`JsonMultiIndex` snapshot artifact.

    Assumes the pointer tuple is already validated and ``size`` resolved
    and rebuildable by the caller; all state is read from the log without
    mutating it. The covered entries, shared batch inclusion proof,
    snapshot root and chain head are computed exactly once and shared by
    every bound pointer's hit groups.
    """
    first = log._retain_from
    if size == 0:
        root = _hash_parts(log._hash_name, _EMPTY_DOMAIN)
    else:
        # Mirror merkle_root: a non-empty prefix released by prune cannot
        # be rebuilt. (The empty root is universal and needs no data.)
        log._require_retained_snapshot(size)
        root = log._fold_occupied(log._occupied_at(size))
    head = log._chain_head_at(size)
    items = tuple(log.entry(index) for index in range(first, size))
    if items:
        _, proof = log.batch_inclusion_proof(tuple(range(first, size)), size)
    else:
        proof = ()
    pointers = tuple(
        _json_pointer_canonical(tokens) for tokens in token_sets
    )
    groups = tuple(
        _json_multi_groups_for_tokens(items, tokens) for tokens in token_sets
    )
    return JsonMultiIndex(
        version=_JSON_MULTI_INDEX_VERSION,
        hash_name=log._hash_name,
        size=size,
        root=root,
        head=head,
        retain_from=first,
        pointers=pointers,
        items=items,
        proof=proof,
        groups=groups,
    )


def _auth_tag(stage: int, entry_hash: bytes, key: bytes, hash_name: str) -> bytes:
    return hmac.new(
        key,
        _AUTH_DOMAIN + stage.to_bytes(_INDEX_BYTES, "big") + entry_hash,
        hash_name,
    ).digest()


def _leaf_hash(entry_hash: bytes, hash_name: str) -> bytes:

def _seal_aad(index: int, previous_hash: bytes) -> bytes:
    return (
        _AAD_DOMAIN
        + bytes((_ALG_AES256_GCM,))
        + index.to_bytes(_INDEX_BYTES, "big")
        + previous_hash
    )


def _seal_envelope(nonce: bytes, sealed: bytes) -> bytes:
    return _ENC_MAGIC + bytes((_ALG_AES256_GCM,)) + nonce + sealed


def _parse_envelope(payload: Any) -> tuple[int, bytes, bytes]:
    """Split an encrypted-entry envelope into ``(algorithm, nonce, sealed)``."""
    if not isinstance(payload, (bytes, bytearray)):
        raise TypeError("entry.payload must be bytes")
    material = bytes(payload)
    if not material.startswith(_ENC_MAGIC):
        raise ValueError("payload is not an auditchain encrypted-entry envelope")
    offset = len(_ENC_MAGIC)
    try:
        algorithm = material[offset]
    except IndexError:
        raise ValueError("truncated envelope: missing algorithm byte") from None
    offset += 1
    if algorithm != _ALG_AES256_GCM:
        raise ValueError(f"unsupported encryption algorithm: {algorithm:#04x}")
    nonce_end = offset + _NONCE_BYTES
    if len(material) < nonce_end:
        raise ValueError("truncated envelope: missing nonce")
    nonce = material[offset:nonce_end]
    sealed = material[nonce_end:]
    if len(sealed) < _GCM_TAG_BYTES:
        raise ValueError("truncated envelope: ciphertext must include a 16-byte tag")
    return algorithm, nonce, sealed


def entry_digest(index: int, previous_hash: bytes, payload: bytes, *, hash_name: str = "sha256") -> bytes:
    """Digest binding an entry to its position and predecessor."""
    if not isinstance(index, int) or index < 0:
        raise ValueError("index must be a non-negative integer")
    digest_size = _digest_size(hash_name)
    previous = bytes(previous_hash)
    if len(previous) != digest_size:
        raise ValueError(f"previous_hash must be {digest_size} bytes")
    digest = hashlib.new(hash_name)
    digest.update(_DOMAIN)
    digest.update(index.to_bytes(_INDEX_BYTES, "big"))
    digest.update(previous)
    digest.update(bytes(payload))
    return digest.digest()


def decrypt_entry(entry: Any, key: Any, *, hash_name: str = "sha256") -> bytes:
    """Decrypt an entry produced by :meth:`AuditLog.encrypt`.

    Validates, in order, that ``entry`` is an :class:`Entry` with a
    well-formed encrypted-entry envelope, that ``key`` is 32 ``bytes``, that
    ``entry.entry_hash`` equals :func:`entry_digest` over the envelope at the
    entry's position, and finally the AES-256-GCM authentication tag with the
    same AAD used when sealing (``b"auditchain/aead/v1\\0" || 0x01 || index
    (u64 big-endian) || previous_hash``). Only then is the plaintext
    returned; plaintext encoding rules are the same as for :meth:`AuditLog.append`
    — callers receive exactly the bytes appended (a ``str`` comes back as its
    UTF-8 encoding). Type errors raise TypeError; a bad key length, a plain
    or malformed envelope, an unknown algorithm, an entry-digest mismatch or
    failed AEAD authentication raise ValueError. The call is read-only and
    never mutates the entry or a log.
    """
    if not isinstance(entry, Entry):
        raise TypeError("entry must be an Entry")
    if not isinstance(hash_name, str):
        raise TypeError("hash_name must be a string")
    _check_key(key)
    if not isinstance(entry.index, int) or isinstance(entry.index, bool):
        raise TypeError("entry.index must be an integer")
    if entry.index < 0 or entry.index >= (1 << 64):
        raise ValueError("entry.index is out of range for the entry framing")
    if not isinstance(entry.previous_hash, (bytes, bytearray)):
        raise TypeError("entry.previous_hash must be bytes")
    if not isinstance(entry.entry_hash, (bytes, bytearray)):
        raise TypeError("entry.entry_hash must be bytes")
    _, nonce, sealed = _parse_envelope(entry.payload)
    digest_size = _digest_size(hash_name)
    previous_hash = bytes(entry.previous_hash)
    if len(previous_hash) != digest_size:
        raise ValueError(f"entry.previous_hash must be {digest_size} bytes")
    expected_hash = entry_digest(
        entry.index,
        previous_hash,
        bytes(entry.payload),
        hash_name=hash_name,
    )
    if not hmac.compare_digest(expected_hash, bytes(entry.entry_hash)):
        raise ValueError("entry.entry_hash does not match the envelope digest")
    aad = _seal_aad(entry.index, previous_hash)
    try:
        return AESGCM(key).decrypt(nonce, sealed, aad)
    except InvalidTag as error:
        raise ValueError("AEAD authentication failed: wrong key or corrupted entry") from error


def _hash_parts(hash_name: str, *parts: bytes) -> bytes:
    digest = hashlib.new(hash_name)
    for part in parts:
        digest.update(part)
    return digest.digest()


def _evolve_key(key: bytes, hash_name: str) -> bytes:
    """Derive the next-stage key; the predecessor key is discarded."""
    return _hash_parts(hash_name, _EVOLVE_DOMAIN, key)


def _locator_digest(payload: bytes, hash_name: str) -> bytes:
    """Content digest used only to locate candidate entries in the index."""
    return _hash_parts(hash_name, _LOCATE_DOMAIN, payload)


def _encrypted_locator_digest(key: bytes, payload: bytes, hash_name: str) -> bytes:
    """Keyed locator digest of an encrypted entry's original plaintext.

    ``HMAC(key, b"auditchain/encrypted-locate/v1\\0" || payload)``: only a
    holder of the append-time key can compute a candidate, and neither the
    plaintext nor the key is stored in the index.
    """
    return hmac.new(key, _ENC_LOCATE_DOMAIN + payload, hash_name).digest()


# --- RFC 6901 JSON Pointer field indexing ---------------------------------

# Query value type tags persisted in a JsonSearchReceipt, keeping the JSON
# scalar kinds apart (True is not 1, "" is not the string "null", ...).
_JSON_TAG_STRING = 0
_JSON_TAG_INTEGER = 1
_JSON_TAG_FLOAT = 2
_JSON_TAG_TRUE = 3
_JSON_TAG_NULL = 4
_JSON_TAG_FALSE = 5

# Sentinel for "this payload yields no queryable scalar at the pointer".
_JSON_MISSING = object()

# Scalar kinds that may appear in a JsonSearchIndex group.
_JSON_INDEX_KINDS = frozenset(
    {
        _JSON_TAG_STRING,
        _JSON_TAG_INTEGER,
        _JSON_TAG_FLOAT,
        _JSON_TAG_TRUE,
        _JSON_TAG_NULL,
        _JSON_TAG_FALSE,
    }
)

# Kinds whose single value is encoded as the empty blob (true / false / null).
_JSON_INDEX_EMPTY_KINDS = frozenset(
    {_JSON_TAG_TRUE, _JSON_TAG_FALSE, _JSON_TAG_NULL}
)

def verify_batch_inclusion(
    indices: Any,
    entry_hashes: Any,
    size: int,
    root: Any,
    proof: Any,
    *,
    hash_name: str = "sha256",
) -> bool:
    """Verify a compact batch inclusion proof without holding the log.

    Checks that the given ``entry_hashes`` are exactly the leaf digests at the
    ascending ``indices`` within a snapshot of ``size`` entries whose Merkle
    root is ``root``, rebuilding it from the single shared ``proof`` produced
    by :meth:`AuditLog.batch_inclusion_proof`. The same recursive split is
    followed (largest power of two below the current length, left half before
    right): an unchosen half contributes its supplied subtree root, a chosen
    half is rebuilt from its leaves and the remaining proof nodes, and odd
    trailing nodes are promoted exactly as for the regular Merkle tree.

    The three sequences must be: a non-empty tuple of strictly ascending
    non-bool integer indices, a tuple of ``bytes`` entry digests of exactly the
    same length and digest width, and a tuple of ``bytes`` proof nodes. Type
    problems raise TypeError; out-of-range or non-ascending indices, mismatched
    sequence or digest widths, a wrong snapshot size or a proof node count that
    does not fit ``(indices, size)`` raise ValueError. Structurally valid
    inputs whose digests, proof or root simply do not match return False.
    """
    if not isinstance(hash_name, str):
        raise TypeError("hash_name must be a string")
    digest_size = _digest_size(hash_name)
    root = _check_digest(root, "root", digest_size)

    if not isinstance(size, int) or isinstance(size, bool):
        raise TypeError("size must be an integer")
    if size < 0:
        raise ValueError("size must be non-negative")

    if not isinstance(indices, tuple):
        raise TypeError("indices must be a tuple of integers")
    if not indices:
        raise ValueError("indices must be non-empty")
    previous = -1
    for index in indices:
        if not isinstance(index, int) or isinstance(index, bool):
            raise TypeError("indices must be non-bool integers")
        if index <= previous:
            raise ValueError("indices must be strictly ascending with no duplicates")
        if index < 0 or index >= size:
            raise ValueError(f"index {index} must satisfy 0 <= index < size ({size})")
        previous = index

    if not isinstance(entry_hashes, tuple):
        raise TypeError("entry_hashes must be a tuple of digests")
    if len(entry_hashes) != len(indices):
        raise ValueError("entry_hashes must have the same length as indices")
    leaves: list[bytes] = []
    for entry_hash in entry_hashes:
        if not isinstance(entry_hash, bytes):
            raise TypeError("entry_hashes elements must be bytes")
        if len(entry_hash) != digest_size:
            raise ValueError(f"entry_hash must be {digest_size} bytes")
        leaves.append(_leaf_hash(entry_hash, hash_name))

    if not isinstance(proof, tuple):
        raise TypeError("proof must be a tuple of digests")
    nodes: list[bytes] = []
    for node in proof:
        if not isinstance(node, bytes):
            raise TypeError("proof elements must be bytes")
        if len(node) != digest_size:
            raise ValueError(f"proof element must be {digest_size} bytes")
        nodes.append(node)

    expected = _batch_proof_length(indices, 0, len(indices), 0, size)
    if len(nodes) != expected:
        raise ValueError(
            f"proof must have {expected} nodes for these indices and size, got {len(nodes)}"
        )

    cursor = 0

    def rebuild(lo: int, hi: int, start: int, length: int) -> bytes:
        nonlocal cursor
        if length == 1:
            return leaves[lo]
        left_count, _ = _batch_split_counts(indices, lo, hi, start, length)
        k = _split_point(length)
        cut = lo + left_count
        if left_count == 0:
            left = nodes[cursor]
            cursor += 1
        else:
            left = rebuild(lo, cut, start, k)
        if hi - cut == 0:
            right = nodes[cursor]
            cursor += 1
